# CELL 3: ANION-CENTRED BVS ENGINE   (Eir 2.0.13)
#
# CHANGED IN 2.0.2
#   Each anion site now records the site multiplicity and which cations
#   coordinate it, and the structure-level summary identifies the worst site
#   rather than only its deviation. Two reasons.
#
#   First, the mean was unweighted across sites. In an ordered pyrochlore the
#   48f oxygen has six times the multiplicity of the 8b, so weighting them
#   equally overstates the mean anion sum by roughly 0.04 v.u. The
#   multiplicity-weighted mean is now reported alongside.
#
#   Second, without knowing WHICH site deviates the number cannot be
#   interpreted. In Fd-3m pyrochlore the 8b oxygen has no free positional
#   parameter: it sits in the A4 tetrahedron at a*sqrt(3)/8, so its bond
#   valence is fixed by the lattice parameter and the A cation cannot relax
#   into it. Measured across 309 ordered RE2B2O7 entries its overbonding
#   tracks rA/rB at r = +0.82 and changes sign at the pyrochlore-fluorite
#   boundary, while the cation GII over the same range is flat. The ligand
#   composition recorded here is what distinguishes that site (four A cations)
#   from the 48f oxygen (two A, two B) without needing a Wyckoff assignment.
# =============================================================================
# ANION-CENTRED BOND VALENCE SUMS
#
# WHAT IT DOES
#   For each crystallographic anion site, sums the bond valence contributions
#   from every neighbouring cation. The bond valence of an M-X bond is the same
#   quantity whichever end you sum it at, so this reuses the existing R0 and b
#   lookup with no new parameters.
#
# WHY IT MATTERS
#   A cation-only BVS cannot tell a bond valence parameter offset from real
#   structural strain. The anion sum can: if the cation deviations cancel at
#   the shared anion, the parameters are mis-calibrated relative to each other
#   and the structure is fine. If the anion also deviates, the problem is real.
#
# TWO DELIBERATE DIFFERENCES FROM THE CATION PATH, both explained below:
#   1. Contributions are weighted by the neighbouring cation's site occupancy.
#   2. No coordination-number gap cut is applied.
# =============================================================================

import math
import tempfile
import numpy as np

# Alias of PROVISIONAL_ANIONS (CELL 1), where the reasoning lives. This was a
# second hand-written copy of the same nine species.
ANION_ELEMENTS = PROVISIONAL_ANIONS

# Distance tolerance for merging symmetry-generated duplicate images.
# NOT a grid snap. ICSD routinely writes special positions as 0.3333 rather
# than 1/3, which makes symmetry images land ~0.002 A apart; a tolerance of
# 1e-3 A double-counts every neighbour, 0.02 A merges them correctly.
ANION_DEDUP_TOL = 0.02

# v2.0.2. ANION_RMAX was 3.5 A, applied as a hard cut on the summation, and
# its comment claimed it matched the cation-side cutoff (which searches to
# 4.2 A). Neither the claim nor the method held up.
#
# In a tilted GdFeO3-type perovskite each oxygen is coordinated by two B and
# four A cations, and the four A-O bonds split under the tilt so that the
# longest exceeds 3.5 A. Measured over 934 ICSD perovskites, 349 of them
# (37%) had an oxygen summed over five cations instead of six, and the sum
# tracked the miscount directly:
#
#     cations found   n     median anion BVS
#     6 (A:4,B:2)    538          2.026
#     5 (A:3,B:2)    327          1.976
#     4               20          1.795
#
# A bias of that size matters because ANION_CONSISTENT_TOL is 0.20 v.u. and
# anion_balances feeds bvs_diagnosis, so a truncated sum can move a structure
# from cation_and_anion_agree to cation_only_deviates.
#
# The summation now terminates on bond valence rather than distance, which is
# what the comment on the summation loop below always claimed it did. A bond
# is included while its contribution s exceeds ANION_BV_CUTOFF; because s
# falls exponentially, the cut-off distance follows from each pair's own R0
# and b rather than from a global number, and is therefore correct for La-O
# (3.88 A) and Ca-O (3.67 A) alike.

# Contribution below which a bond is not worth counting, in valence units.
# Editable; 0.04 is the default and the reason is a hard constraint, not taste.
#
# The anion sum is only useful because it is compared with the cation sum, and
# a difference between them is read as evidence about the parameters. That
# comparison is only valid if both span the SAME coordination shell. The
# cation side gap-cuts to the first shell, so the anion cut-off has to be
# tight enough to exclude the second.
#
# Rock salt sets the limit. In MgO the second cation shell lies at a*sqrt(3)/2
# and holds eight neighbours; at a = 4.18937 A that is 3.628 A, where
# s = 0.01046 for Mg-O. A cut-off of 0.01 admits all eight, adding 0.084 v.u.,
# so the anion sum reads 2.084 against a cation sum of 2.000 for the same
# bonds. VALIDATE() test 6 fails on exactly that. At 0.04 the second shell is
# excluded (it would have to reach 3.034 A to count) and the two sums agree.
#
#     cut-off   Mg-O reach   MgO 2nd shell (3.628 A)   test 6
#       0.01       3.65 A            included          FAIL
#       0.04       3.03 A            excluded          pass
#
# Nothing is lost at the loose end: on a tilted LaTiO3-type perovskite the
# anion sums are identical at 0.04, at 0.01 and under the old fixed 3.5 A cut,
# because the fourth A-O bond of a strongly tilted structure lies beyond all
# three and is genuinely too long to be a bond.
#
# Lowering this below about 0.02 will start to admit second shells and break
# the cation-anion comparison. Raise it to tighten the first shell.
# v2.0.3: the anion cut-off is no longer independent. s is a property of the
# bond, so a contact admitted to the cation sum must be admitted to the anion
# sum; the previous 0.04 counted bonds in 0.02 <= s < 0.04 at one end only.
#
# MEASURED, not argued. An earlier note here warned that lowering the cut-off
# below about 0.02 would admit second shells. The opposite is true. On 831
# clean ICSD perovskites the modal oxygen coordination is 5 at 0.04 and 6 at
# 0.02, where the structure type requires 2 B + 4 A = 6. Of 491 anion sites
# that gained coordination on the change, EVERY one went from [A:3, B:2] to
# [A:4, B:2]: the B count never moved and nothing exceeded 6. The old cut-off
# was truncating the fourth A-O bond, which is the long bond to a large
# period-4-6 cation that Gagne & Hawthorne (2015) sec 4 name explicitly as
# one to include. 0.02 also gives the anion sum closest to formal (mean
# 1.9990 against 1.9894 at 0.04) and the fewest sites outside
# ANION_CONSISTENT_TOL. Mean |deviation| is flat at 0.090 across all four
# cut-offs tested, so the residual anion scatter is not a shell problem and
# lowering the cut further will not address it.
#
# See BV_SUM_CUTOFF in CELL 1 for the cation-side derivation and the sourcing.
# v2.0.13 NOTE. The cation side now also has an adaptive boundary set from
# each ion's own Lewis acidity and Gagne's measured bond lengths
# (bv_shell_boundary, CELL 1), currently exported but not canonical. When it
# becomes canonical this alias must follow it, or the two ends of the same
# bond will once more be summed under different rules - which is the
# asymmetry v2.0.3 removed by making this an alias in the first place.
ANION_BV_CUTOFF = BV_SUM_CUTOFF

# Neighbour SEARCH radius only, not a summation cut. Must exceed the distance
# at which s falls to ANION_BV_CUTOFF for the largest R0 in use: Ba-O at
# R0 = 2.29 reaches 0.04 v.u. at 3.48 A and 0.01 v.u. at 3.99 A, so 5.0 A
# leaves margin for a lowered cut-off without needing to be changed with it.
ANION_RMAX = 5.0
ANION_CONSISTENT_TOL = 0.20   # |BVS - formal| below which the anion "balances"


def _load_structure_for_anion_bvs(cif_path):
    """Read a CIF into a gemmi SmallStructure, reusing Eir's CIF cleaning."""
    import gemmi
    import os as _os

    cleaned = clean_cif_for_gemmi(cif_path)
    if cleaned is None:
        return None

    with tempfile.NamedTemporaryFile(mode='w', suffix='.cif', delete=False,
                                     encoding='utf-8') as tmp:
        tmp.write(cleaned)
        tmp_path = tmp.name
    try:
        st = gemmi.make_small_structure_from_block(gemmi.cif.read(tmp_path).sole_block())
    finally:
        try:
            _os.unlink(tmp_path)
        except OSError:
            pass          # temp file already gone; nothing depends on it

    if st is None or len(st.sites) == 0:
        return None

    # Some ICSD entries leave gemmi unable to resolve the group from the H-M
    # symbol alone; fall back to the International Tables number.
    if st.spacegroup is None:
        import re as _re
        m = (_re.search(r'_space_group_IT_number\s+(\d+)', cleaned)
             or _re.search(r'_symmetry_Int_Tables_number\s+(\d+)', cleaned))
        if m:
            st.spacegroup = gemmi.find_spacegroup_by_number(int(m.group(1)))
    if st.spacegroup is None:
        return None
    return st


# v2.0.41: TWO SYMMETRY IMAGES EITHER COINCIDE OR THEY DO NOT.
#
# This is a test for the SAME atom reached by two operations, so the only
# tolerance it needs is the one that absorbs floating-point noise in the
# rotation and the wrap. It is not a test for atoms that are close together,
# and the value it carried until now made it one.
#
# The old default was 0.02 fractional. In an 8.4 A spinel cell that is 0.17 A,
# and a site 0.17 A from a special position is merged into that position.
# Measured on a synthetic Fd-3m with one site at (u,u,u), a = 8.4 A:
#
#     u = 0.75047   tol 0.02 -> 8    tol 1e-4 -> 32   (32e, NOT special)
#     u = 0.755     tol 0.02 -> 8    tol 1e-4 -> 32
#     u = 0.625     tol 0.02 -> 16   tol 1e-4 -> 16   (16d, genuinely special)
#
# 0.75047 is ICSD 38769's O1. The 2.0.40 edit script caught it from the other
# side: the depositor writes multiplicity 32 and this counter returned 8, the
# only disagreement in 671 sites across 150 spinels.
#
# The floor is set by how far apart two genuinely distinct images get. Measured
# over those same 671 sites, the closest pair of distinct images is 0.214
# fractional, 1.75 A, on ICSD 86168 Li1 - a thousand times this tolerance. And
# 1e-4 fractional is 8.4e-4 A in that cell, ten orders of magnitude above
# double-precision noise. There is no value in between that changes an answer.
SITE_IMAGE_TOL = 1.0e-4      # fractional; 8.4e-4 A in an 8.4 A cell


def site_multiplicities(st, tol=SITE_IMAGE_TOL):
    """
    Number of distinct atoms per site label in one unit cell.

    v2.0.2. Needed to weight the anion sites: reporting an unweighted mean
    over sites treats a 48-fold and an 8-fold oxygen as equal contributors,
    which they are not. Counted from the symmetry operations rather than
    read from a Wyckoff table, so it needs no lookup and works in any setting.

    v2.0.41: the default tolerance was 0.02 and is now SITE_IMAGE_TOL. See the
    measurement above. This function feeds anion_bvs_mean_weighted,
    anion_deviation_mean_weighted and anion_worst_multiplicity; the Bond_Str
    indices read the DEPOSITED multiplicity and are unaffected.
    """
    # v2.0.26: 125,868 generator calls over twenty spinels, asking the same
    # question as the two dedups in CELL 2 and below - but NOT the same
    # test, so not the same helper. This one is per-axis and PERIODIC:
    # three independent wrapped comparisons, not a Euclidean distance. It
    # gets the same treatment inline, with the bucket index taken modulo the
    # number of buckets so that 0.999 and 0.001 are neighbours, which is the
    # whole point of the wrap in the original.
    #
    # floor rather than ceil for the bucket count, so the bucket edge is at
    # least tol and a pair within tol is never two buckets apart.
    _nb = max(1, int(math.floor(1.0 / tol)))
    out = {}
    for s in st.sites:
        seen = []
        _buckets = {}
        for op in st.spacegroup.operations():
            # v2.0.35: the same wrap as every other expansion, from one
            # definition. This one was already correct - it is the only place
            # that wrapped - and it is here so there is no second rule.
            f = wrap_into_cell(op.apply_to_xyz(
                [s.fract.x, s.fract.y, s.fract.z]))
            _k = tuple(int(x * _nb) % _nb for x in f)
            _dup = False
            for _d0 in (-1, 0, 1):
                for _d1 in (-1, 0, 1):
                    for _d2 in (-1, 0, 1):
                        _kk = ((_k[0] + _d0) % _nb, (_k[1] + _d1) % _nb,
                               (_k[2] + _d2) % _nb)
                        for g in _buckets.get(_kk, ()):
                            if all(min(abs(a - b), 1.0 - abs(a - b)) < tol
                                   for a, b in zip(f, g)):
                                _dup = True
                                break
                        if _dup:
                            break
                    if _dup:
                        break
                if _dup:
                    break
            if not _dup:
                seen.append(f)
                _buckets.setdefault(_k, []).append(f)
        out[s.label] = len(seen)
    return out


def _expand_cell(st, rmax=None):
    """
    All symmetry images of every site, over enough unit cells to cover rmax.

    v2.0.2: the block is now sized from the search radius and the cell edges
    instead of being fixed at 3x3x3. A fixed one-cell margin covers a 3.5 A
    search only while every edge exceeds 3.5 A; for a simple cubic perovskite
    at a = 3.8 A it was already marginal, and raising the search radius to
    5.0 A would have silently lost neighbours across the cell boundary.
    """
    import gemmi
    # v2.0.35: one range rule, from the interplanar spacings, and the image
    # wrapped into the cell. The anion sums and WAGII read this expansion, so
    # they were losing the same contacts the bond list was: on ICSD 23164 the
    # two oxygens found 8 and 9 neighbours inside 3 A where there are 13.
    n = image_range(st.cell, rmax)
    span = range(-n, n + 1)
    pts = []
    for s in st.sites:
        for op in st.spacegroup.operations():
            f = wrap_into_cell(op.apply_to_xyz(
                [s.fract.x, s.fract.y, s.fract.z]))
            for i in span:
                for j in span:
                    for k in span:
                        p = st.cell.orthogonalize(
                            gemmi.Fractional(f[0] + i, f[1] + j, f[2] + k))
                        pts.append((s.label, s.element.name, s.occ, p.x, p.y, p.z))
    return pts


# v2.0.44: tolerance on a cation's void-guard limit when read from the anion
# end, where the same distance is recomputed from the other atom.
SHELL_LIMIT_TOL = 0.01        # A


import collections

# v2.0.46: what _are_alternatives needs of a neighbour
_AltSite = collections.namedtuple('_AltSite', 'label occ')


def calculate_anion_bvs(cif_path, valences, rmax=ANION_RMAX, verbose=False,
                        shell_limits=None):
    """
    Anion-centred bond valence sums for one structure.

    Args:
        cif_path : path to the CIF
        valences : {element_or_site_label: valence}, the SAME dict used for the
        cation-side sums. Site labels take precedence over elements, so a
        structure with one element at two valences is summed correctly.
                   calculation, so the two are directly comparable
        rmax     : neighbour cutoff in Angstrom
        verbose  : print the per-bond breakdown
        shell_limits : v2.0.44, {cation site label: longest bond in its
                   shell} for the cations whose shell the void guard cut.
                   A contact beyond it is not a bond from this end either.

    Returns:
        list of dicts, one per crystallographic anion site:
            anion_label, anion_element, anion_cn, anion_bvs,
            anion_bvs_unweighted, anion_expected, anion_deviation,
            anion_contributions, n_missing_params
        Returns [] if the structure cannot be read.
    """
    st = _load_structure_for_anion_bvs(cif_path)
    if st is None:
        return []

    pts = _expand_cell(st, rmax)
    # v2.0.2: atoms per site label in one cell, for weighting the sites.
    # Never allowed to be fatal. Multiplicity is an enhancement to the
    # reporting; losing it costs a weighted mean, whereas letting it raise
    # costs the whole structure. On the first run of this code exactly that
    # happened to one perovskite of 934, which silently dropped from
    # anion_only_deviates to insufficient_data.
    try:
        _multiplicity = site_multiplicities(st)
    except (NameError, AttributeError, TypeError):
        # A defect in site_multiplicities, not a property of the CIF. The
        # note above is right that losing multiplicity must not cost the
        # structure, but a broken function must not present as a structure
        # that happens to have none.
        raise
    except Exception as _e:
        _multiplicity = {}
        # Not conditional on verbose: a weighted mean silently becoming an
        # unweighted one is exactly the kind of quiet degradation this
        # notebook keeps finding.
        print(f'  [site multiplicities unavailable, mean will be unweighted: '
              f'{type(_e).__name__}: {_e}]')
    # v2.0.26: 1.31 s over twenty spinels, building 15,552 three-element
    # lists so numpy could copy them. fromiter reads the same floats
    # straight into the buffer. Same array, same values, no intermediate.
    P = np.fromiter((c for a in pts for c in (a[3], a[4], a[5])),
                    dtype=np.float64, count=3 * len(pts)).reshape(-1, 3)

    # v2.0.46: a halogen stated positive is a cation here, decided per site
    # so that a chloride perchlorate keeps its chloride (positive_halogens).
    def _is_anion_site(label, element):
        if element not in ANION_ELEMENTS:
            return False
        v = valences.get(label, valences.get(element))
        try:
            return not (element in ALWAYS_ANION and float(v) > 0)
        except (TypeError, ValueError):
            return True

    # v2.0.46: positions the model fills one at a time are not neighbours
    # (_are_alternatives), as the cation side's bond finder already has it
    _alt_esd = _occupancy_esds(cif_path)

    results = []
    for site in st.sites:
        if not _is_anion_site(site.label, site.element.name):
            continue

        o = site_centre(st.cell, site)
        p0 = np.array([o.x, o.y, o.z])
        d = np.linalg.norm(P - p0, axis=1)
        cand = np.where((d > 0.01) & (d <= rmax))[0]
        cand = cand[np.argsort(d[cand])]

        # Deduplicate symmetry images WITHIN each site label only.
        # Two different labels at the same coordinates are a mixed-occupancy
        # site and BOTH are real neighbours. Deduplicating on position alone
        # silently deletes the minority species: on a set of P2 layered oxides that
        # removed the Ni from every Mn/Ni site and pulled the mean anion sum
        # from 2.11 down to 1.68.
        # v2.0.26: one PointDedup per site label, replacing a linear scan
        # that called np.linalg.norm on a 3-vector for every pair - 77,429
        # calls over twenty spinels, at roughly 7 us each against 0.3 us for
        # the same arithmetic in math. The dedup stays PER LABEL for the
        # reason above: two labels at one position are a mixed-occupancy
        # site and both are real neighbours.
        kept = {}
        neighbours = []
        _Pl = P.tolist()
        for idx in cand:
            label, elem, occ = pts[idx][0], pts[idx][1], pts[idx][2]
            if _is_anion_site(label, elem):
                continue
            if (d[idx] < CATION_ANION_ABSOLUTE_MIN
                    and elem not in CATION_FLOOR_EXCLUDED_ELEMENTS
                    and site.element.name not in CATION_FLOOR_EXCLUDED_ELEMENTS
                    and _are_alternatives(site, _AltSite(label, occ), _alt_esd)):
                continue                          # v2.0.46
            _px, _py, _pz = _Pl[idx]
            _dd = kept.get(label)
            if _dd is None:
                _dd = kept[label] = PointDedup(ANION_DEDUP_TOL, strict=True)
            if _dd.seen_or_add(_px, _py, _pz):
                continue
            neighbours.append((float(d[idx]), label, elem, occ))
        neighbours.sort()

        anion_elem = site.element.name
        expected = abs(valences.get(anion_elem, -2))
        # v2.0.46: given this anion, no more polyanion centres than
        # POLYANION_MOST_CENTRES, or the plain occupancies stand
        _given = site.occ
        if sum(conditional_occupancy(occ, _given, elem, anion_elem, dist)
               for dist, label, elem, occ in neighbours
               if polyanion_bond(elem, anion_elem, dist)
               ) > POLYANION_MOST_CENTRES + 0.25:
            _given = None

        total = 0.0
        total_unweighted = 0.0
        n_missing = 0
        n_counted = 0
        _counted_elements = []
        parts = []

        for dist, label, elem, occ in neighbours:
            # v2.0.44: "a contact admitted to the cation sum must be admitted
            # to the anion sum" (BV_SUM_CUTOFF), and so must one refused. Only
            # cations whose shell the void guard cut are listed.
            _lim = (shell_limits or {}).get(label)
            if _lim is not None and dist > _lim + SHELL_LIMIT_TOL:
                continue
            # v2.0.13: LABEL first, element second. The map is keyed by both;
            # keying it by element alone gave every site of an element the
            # same valence, so in Co3O4 the 8a Co(2+) and the 16d Co(3+)
            # were summed with one R0 chosen by list order. 147 of 1881
            # spinels (7.8%), 10 of 472 pyrochlores and 2 of 938 perovskites
            # carry an element at two valences.
            v = valences.get(label)
            if v is None:
                v = valences.get(elem)
            if v is None:
                n_missing += 1
                continue
            R0, b = get_bv_parameters_fractional(elem, v, anion_elem)
            if R0 is None:
                n_missing += 1
                continue
            s = math.exp((R0 - dist) / b)
            # v2.0.2: terminate on bond valence, not distance. See
            # ANION_BV_CUTOFF. A neighbour inside the search radius whose
            # contribution is below the cut-off is not a bond.
            if s < ANION_BV_CUTOFF:
                continue
            n_counted += 1
            _counted_elements.append(elem)
            # Occupancy weighting. On the cation side the ligands are anions,
            # which are almost always fully occupied, so this rarely matters.
            # On the anion side the ligands are cations, which in layered
            # oxides are routinely 30-70% occupied, so it is essential: the
            # average oxygen sees only the occupied fraction of each cation
            # site. This is the same argument as WAGII, applied per bond.
            # v2.0.46: a bond inside a polyanion counts at the chance its
            # cation is there given this anion is (conditional_occupancy)
            _wt = conditional_occupancy(occ, _given, elem, anion_elem, dist)
            total += _wt * s
            total_unweighted += s
            parts.append(f"{elem}({label}) {dist:.3f}A occ{occ:.2f}"
                         + (f" given this site {_wt:.2f}" if _wt != occ else '')
                         + f" s={s:.3f}")

        # No gap cut is applied. Bond valence falls off exponentially and
        # terminates itself; cutting the shell at the largest geometric gap
        # cannot separate the two halves of a split site, which is exactly
        # where the anion sum is most informative.
        # v2.0.2: which cations coordinate this anion, and how many of each.
        # This is what separates the two oxygen sites of a pyrochlore without
        # needing a Wyckoff assignment: the 8b oxygen is coordinated by four A
        # cations and nothing else, the 48f by two A and two B.
        # Accepted bonds only. Counting the searched neighbours instead
        # reports every cation inside the search radius as a ligand, which
        # after the radius was widened to 5.0 A meant 18 "ligands" on an
        # oxygen with five bonds.
        _lig = {}
        for _el in _counted_elements:
            _lig[_el] = _lig.get(_el, 0) + 1
        _lig_txt = ','.join(f'{e}:{c}' for e, c in
                            sorted(_lig.items(), key=lambda kv: (-kv[1], kv[0])))

        results.append({
            'anion_label': site.label,
            'anion_element': anion_elem,
            # bonds actually counted, not neighbours found inside the
            # search radius; the two differ by the bond-valence cut-off
            'anion_cn': n_counted,
            'anion_neighbours_searched': len(neighbours),
            'anion_bv_cutoff': ANION_BV_CUTOFF,
            'anion_multiplicity': _multiplicity.get(site.label),
            'anion_ligands': _lig_txt or None,
            'anion_n_ligand_species': len(_lig),
            'anion_bvs': round(total, 4),
            'anion_bvs_unweighted': round(total_unweighted, 4),
            'anion_expected': expected,
            'anion_deviation': round(total - expected, 4),
            'anion_contributions': '; '.join(parts) if parts else None,
            'n_missing_params': n_missing,
        })

        if verbose:
            print(f"  {site.label} ({anion_elem}): CN={n_counted}  "
                  f"BVS={total:.3f}  expected {expected:.1f}  "
                  f"dev {total - expected:+.3f}")
            for p in parts:
                print(f"      {p}")

    return results


def summarise_anion_bvs(anion_results, cation_gii=None):
    """
    Collapse per-site anion results into structure-level diagnostic fields.

    anion_balances : True if every anion site sums to its formal charge within
                     ANION_CONSISTENT_TOL. When this is True but the cation GII
                     is large, the cation deviations are cancelling at the
                     shared anion, which points at the bond valence parameters
                     rather than at the structure.
    """
    # v2.0.2: filter ONCE and keep the records alongside their deviations.
    # Previously `devs` was filtered while the per-record lists below were not,
    # so any site with a missing deviation misaligned the index used to pick
    # the worst site, and made the weighted average raise on a length mismatch.
    kept = [r for r in anion_results if r.get('anion_deviation') is not None]
    vals = [r['anion_deviation'] for r in kept]
    if not vals:
        # Every key the normal return provides, so a structure with no usable
        # anion sites yields the same columns rather than absent ones.
        return {'n_anion_sites': 0,
                'anion_bvs_mean': None, 'anion_bvs_mean_weighted': None,
                'anion_deviation_mean': None, 'anion_deviation_mean_weighted': None,
                'anion_deviation_max': None, 'anion_deviation_range': None,
                'anion_worst_label': None, 'anion_worst_cn': None,
                'anion_worst_multiplicity': None, 'anion_worst_ligands': None,
                'anion_worst_bvs': None,
                'anion_balances': None, 'bvs_diagnosis': None}

    devs = np.array(vals)
    balances = bool(np.all(np.abs(devs) <= ANION_CONSISTENT_TOL))

    diagnosis = None
    if cation_gii is not None:
        if cation_gii > 0.30 and balances:
            diagnosis = 'parameter_offset'
        elif cation_gii > 0.30 and not balances:
            diagnosis = 'structure_or_data_problem'
        elif cation_gii <= 0.30 and balances:
            diagnosis = 'consistent'
        else:
            diagnosis = 'check_anion'

    # v2.0.2: multiplicity-weighted mean alongside the unweighted one. The
    # unweighted mean treats every crystallographic site as one contributor
    # regardless of how many atoms sit on it; for a pyrochlore that gives the
    # 8-fold oxygen the same weight as the 48-fold one.
    _bvs = [r['anion_bvs'] for r in kept]
    _mult = [r.get('anion_multiplicity') for r in kept]
    if _mult and all(m for m in _mult) and len(_mult) == len(devs):
        _w = np.array(_mult, float)
        _bvs_w = round(float(np.average(_bvs, weights=_w)), 4)
        _dev_w = round(float(np.average(devs, weights=_w)), 4)
    else:
        _bvs_w = _dev_w = None

    # v2.0.2: which site deviates most, and what coordinates it. A deviation
    # with no site attached cannot be interpreted; with the ligand composition
    # it usually can.
    _worst = kept[int(np.argmax(np.abs(devs)))]

    return {
        'n_anion_sites': len(devs),
        'anion_bvs_mean': round(float(np.mean(_bvs)), 4),
        'anion_bvs_mean_weighted': _bvs_w,
        'anion_deviation_mean': round(float(devs.mean()), 4),
        'anion_deviation_mean_weighted': _dev_w,
        'anion_deviation_max': round(float(devs[np.argmax(np.abs(devs))]), 4),
        'anion_deviation_range': round(float(devs.max() - devs.min()), 4),
        'anion_worst_label': _worst.get('anion_label'),
        'anion_worst_cn': _worst.get('anion_cn'),
        'anion_worst_multiplicity': _worst.get('anion_multiplicity'),
        'anion_worst_ligands': _worst.get('anion_ligands'),
        'anion_worst_bvs': _worst.get('anion_bvs'),
        'anion_balances': balances,
        'bvs_diagnosis': diagnosis,
    }


print("Anion-centred BVS loaded: calculate_anion_bvs(), summarise_anion_bvs()")


# =============================================================================
# SELF-TEST
#
# Paste into a NEW cell below and run. It writes two small CIFs to a temporary
# directory, so it needs no files from you and leaves nothing behind.
#
# Tests 1 and 3 are parameter-independent: they check the crystallography, and
# they must pass. Test 2 prints a number that depends on your R0 and b values.
# =============================================================================

def _test_anion_bvs():
    import os, tempfile, textwrap

    nacro2 = textwrap.dedent("""\
        data_test_NaCrO2
        _cell_length_a 2.9719
        _cell_length_b 2.9719
        _cell_length_c 15.9710
        _cell_angle_alpha 90.
        _cell_angle_beta 90.
        _cell_angle_gamma 120.
        _space_group_name_H-M_alt 'R -3 m H'
        _space_group_IT_number 166
        loop_
        _atom_site_label
        _atom_site_type_symbol
        _atom_site_fract_x
        _atom_site_fract_y
        _atom_site_fract_z
        _atom_site_occupancy
        Na1 Na1+ 0. 0. 0. 1.
        Cr1 Cr3+ 0. 0. 0.5 1.
        O1 O2- 0. 0. 0.2325 1.
        """)

    # Mn and Ni deliberately share (0,0,0), as in ICSD 208051.
    shared = textwrap.dedent("""\
        data_test_shared_site
        _cell_length_a 2.8810
        _cell_length_b 2.8810
        _cell_length_c 11.2060
        _cell_angle_alpha 90.
        _cell_angle_beta 90.
        _cell_angle_gamma 120.
        _space_group_name_H-M_alt 'P 63/m m c'
        _space_group_IT_number 194
        loop_
        _atom_site_label
        _atom_site_type_symbol
        _atom_site_fract_x
        _atom_site_fract_y
        _atom_site_fract_z
        _atom_site_occupancy
        Na1 Na1+ 0.6667 0.3333 0.25 0.35
        Mn1 Mn3+ 0. 0. 0. 0.667
        Ni1 Ni3+ 0. 0. 0. 0.333
        O1 O2- 0.6667 0.3333 0.0905 1.
        """)

    d = tempfile.mkdtemp()
    pa = os.path.join(d, 'nacro2.cif'); open(pa, 'w').write(nacro2)
    pb = os.path.join(d, 'shared.cif'); open(pb, 'w').write(shared)

    ok = True

    print("TEST 1 - symmetry expansion and duplicate merging (NaCrO2)")
    r1 = calculate_anion_bvs(pa, {'Na': 1, 'Cr': 3, 'O': -2})
    if not r1:
        print("   FAIL: no anion sites returned"); return False
    a = r1[0]
    n_cr = a['anion_contributions'].count('Cr(')
    n_na = a['anion_contributions'].count('Na(')
    print(f"   oxygen CN = {a['anion_cn']}  ({n_cr} Cr + {n_na} Na)   expected 6 (3 + 3)")
    if not (a['anion_cn'] == 6 and n_cr == 3 and n_na == 3):
        print("   FAIL"); ok = False
    else:
        print("   pass")

    print("\nTEST 2 - anion sum (depends on your R0 and b values)")
    print(f"   anion BVS = {a['anion_bvs']:.3f}, expected 2.000, deviation {a['anion_deviation']:+.3f}")
    if 1.90 <= a['anion_bvs'] <= 2.05:
        print("   pass - consistent with Gagne & Hawthorne parameters")
    else:
        print("   NOTE - outside 1.90-2.05. Not necessarily wrong, but check")
        print("          which parameter set the database is supplying.")

    print("\nTEST 3 - mixed-occupancy site (Mn and Ni both at 0,0,0)")
    r2 = calculate_anion_bvs(pb, {'Na': 1, 'Mn': 3, 'Ni': 3, 'O': -2})
    if not r2:
        print("   FAIL: no anion sites returned"); return False
    c = r2[0]['anion_contributions'] or ''
    has_mn, has_ni = 'Mn(' in c, 'Ni(' in c
    print(f"   Mn present: {has_mn}   Ni present: {has_ni}   (both must be True)")
    if not (has_mn and has_ni):
        print("   FAIL - the minority species is being deleted by deduplication"); ok = False
    else:
        print("   pass")

    print("\nTEST 4 - occupancy weighting is active")
    w, u = r2[0]['anion_bvs'], r2[0]['anion_bvs_unweighted']
    print(f"   weighted {w:.3f}  vs unweighted {u:.3f}")
    if u > w * 1.05:
        print("   pass")
    else:
        print("   FAIL - weighting does not appear to be applied"); ok = False

    print("\n" + ("ALL STRUCTURAL TESTS PASSED." if ok else "SOMETHING FAILED - see above."))
    return ok


_test_anion_bvs()